+/// Ctrl+D character (EOT / End-of-Transmission). Treated as "cancel" in all
+/// interactive prompts so the user can abort cleanly instead of getting stuck.
+const CTRL_D: char = '\x04';
+
 /// Convert dialoguer errors to BivvyError.
 fn map_dialoguer_err(e: dialoguer::Error) -> BivvyError {
     BivvyError::Io(e.into())
 }

+/// Run a dialoguer interaction, catching any panic (e.g., from an internal
+/// `.unwrap()` on EOF when Ctrl+D is pressed) and converting it to an IO error.
+fn catch_dialoguer_panic<T>(f: impl FnOnce() -> Result<T>) -> Result<T> {
+    match catch_unwind(AssertUnwindSafe(f)) {
+        Ok(result) => result,
+        Err(_) => Err(BivvyError::Io(std::io::Error::new(
+            std::io::ErrorKind::Interrupted,
+            "prompt cancelled (Ctrl+D)",
+        ))),
+    }
